mapper.select:
SELECT p.*,p.source_record_key AS raw_key FROM com_shipment_package p
WHERE p.tenant_id=#{tenantId} AND p.deleted=FALSE AND p.source_system='DPPMS'
ORDER BY p.id LIMIT #{limit}

SELECT c.*,c.master_source_record_key AS raw_key FROM com_contract c
WHERE c.tenant_id=#{tenantId} AND c.deleted=FALSE AND c.master_source_system='DPPMS_ERP'
ORDER BY c.id LIMIT #{limit}
